11	// Author: Tan, Zhiyuan
12	// Description: Lsu missing status holding registers
13	
14	`timescale 1ns/1ns
15	`include "define.v"
16	
17	module mshr (
18	  input                                             clk                       ,
19	  input                                             rst_n                     ,
20	
21	  //from mshr
22	  input                                             from_addr_valid_i         ,
23	  output                                            from_addr_ready_o         ,
24	  input   [`DEPTH_WARP-1:0]                         from_addr_warp_id_i       ,
25	  input                                             from_addr_wfd_i           ,
26	  input                                             from_addr_wxd_i           ,
27	  //input                                             from_addr_isvec_i         ,
28	  input   [`REGIDX_WIDTH+`REGEXT_WIDTH-1:0]         from_addr_reg_idxw_i      ,
29	  input   [`NUM_THREAD-1:0]                         from_addr_mask_i          ,
30	  input                                             from_addr_unsigned_i      ,
31	  input   [`BYTESOFWORD*`NUM_THREAD-1:0]            from_addr_wordoffset1h_i  ,
32	  input                                             from_addr_iswrite_i       ,
33	
34	  //send idx_entry to addr
35	  output  [$clog2(`LSU_NMSHRENTRY)-1:0]             idx_entry_o               ,
36	
37	  //from dcache/shared
38	  input                                             from_dcache_valid_i       ,
39	  output                                            from_dcache_ready_o       ,
40	  input   [$clog2(`LSU_NMSHRENTRY)-1:0]             from_dcache_instrid_i     ,
41	  input   [`XLEN*`NUM_THREAD-1:0]                   from_dcache_data_i        ,
42	  input   [`NUM_THREAD-1:0]                         from_dcache_activemask_i  ,
43	
44	  //to pipe
45	  output                                            to_pipe_valid_o           ,
46	  input                                             to_pipe_ready_i           ,
47	  output  [`DEPTH_WARP-1:0]                         to_pipe_warp_id_o         ,
48	  output                                            to_pipe_wfd_o             ,
49	  output                                            to_pipe_wxd_o             ,
50	  //output                                            to_pipe_isvec_o           ,
51	  output  [`REGIDX_WIDTH+`REGEXT_WIDTH-1:0]         to_pipe_reg_idxw_o        ,
52	  output  [`NUM_THREAD-1:0]                         to_pipe_mask_o            ,
53	  //output                                            to_pipe_unsigned_o        ,
54	  //output  [`BYTESOFWORD*`NUM_THREAD-1:0]            to_pipe_wordoffset1h_o    ,
55	  output                                            to_pipe_iswrite_o         ,
56	  output  [`XLEN*`NUM_THREAD-1:0]                   to_pipe_data_o            
57	);
58	
59	  wire to_pipe_unsigned;
60	  wire [`BYTESOFWORD*`NUM_THREAD-1:0] to_pipe_wordoffset1h;
61	  
62	  //mshr entry size: LSU_NMSHRENTRY
63	  //sram wires
64	  wire                               sram_in_data_ren  ;
65	  wire [$clog2(`LSU_NMSHRENTRY)-1:0] sram_in_data_raddr;
66	  reg                                sram_in_data_wen  ;
67	  reg  [$clog2(`LSU_NMSHRENTRY)-1:0] sram_in_data_waddr;
68	  reg  [`XLEN*`NUM_THREAD-1:0]       sram_in_data_wmask;
69	  reg  [`XLEN*`NUM_THREAD-1:0]       sram_in_data_bits ;
70	  wire [`XLEN*`NUM_THREAD-1:0]       sram_out_data_bits;
71	
72	  wire                                                             sram_in_tag_ren  ;
73	  wire [$clog2(`LSU_NMSHRENTRY)-1:0]                               sram_in_tag_raddr;
74	  reg                                                              sram_in_tag_wen  ;
75	  wire [$clog2(`LSU_NMSHRENTRY)-1:0]                               sram_in_tag_waddr;
76	  wire [3+`NUM_THREAD*5+`REGIDX_WIDTH+`REGEXT_WIDTH+`DEPTH_WARP:0] sram_in_tag_wmask;
77	  wire [3+`NUM_THREAD*5+`REGIDX_WIDTH+`REGEXT_WIDTH+`DEPTH_WARP:0] sram_in_tag_bits ;
78	  wire [3+`NUM_THREAD*5+`REGIDX_WIDTH+`REGEXT_WIDTH+`DEPTH_WARP:0] sram_out_tag_bits;
79	
80	  wire [`DEPTH_WARP-1:0]                 sram_in_tag_warp_id     ;
81	  wire                                   sram_in_tag_wfd         ;
82	  wire                                   sram_in_tag_wxd         ;
83	  wire [`REGIDX_WIDTH+`REGEXT_WIDTH-1:0] sram_in_tag_reg_idxw    ;
84	  wire [`NUM_THREAD-1:0]                 sram_in_tag_mask        ;
85	  wire                                   sram_in_tag_unsigned    ;
86	  wire [`BYTESOFWORD*`NUM_THREAD-1:0]    sram_in_tag_wordoffset1h;
87	  wire                                   sram_in_tag_iswrite     ;
88	
89	  //current mask and used information
90	  reg  [`NUM_THREAD*`LSU_NMSHRENTRY-1:0]                   current_mask    ;
91	  reg  [`LSU_NMSHRENTRY-1:0]                               used            ;
92	
93	  //reg_req
94	  reg  [`NUM_THREAD-1:0]             reg_req_mask       ;
95	
96	  //inv_activemask
97	  wire [`NUM_THREAD-1:0]             inv_activemask     ;
98	  
99	  assign inv_activemask = ~from_dcache_activemask_i;
100	  
101	  //PriorityEncoder: complete, ~used
102	  wire [`LSU_NMSHRENTRY-1:0]         complete           ;
103	  wire [`LSU_NMSHRENTRY-1:0]         pri_complete_oh    ;
104	  wire [$clog2(`LSU_NMSHRENTRY)-1:0] pri_complete_bin   ;
105	  wire [`LSU_NMSHRENTRY-1:0]         pri_nused_oh       ;
106	  wire [$clog2(`LSU_NMSHRENTRY)-1:0] pri_nused_bin      ;
107	
108	  genvar n;
109	  generate for(n=0;n<`LSU_NMSHRENTRY;n=n+1) begin: COMPLETE //assign complete
110	    assign complete[n]      = (current_mask[`NUM_THREAD*(n+1)-1-:`NUM_THREAD]=='d0) && used[n] ;
111	  end
112	  endgenerate
113	  
114	  fixed_pri_arb #(
115	    .ARB_WIDTH  (`LSU_NMSHRENTRY) 
116	  )
117	  complete_oh(
118	    .req    (complete       ) ,
119	    .grant  (pri_complete_oh)   
120	  );
121	
122	  one2bin #(
123	    .ONE_WIDTH  (`LSU_NMSHRENTRY        ) ,
124	    .BIN_WIDTH  ($clog2(`LSU_NMSHRENTRY)) 
125	  )
126	  complete_bin(
127	    .oh    (pri_complete_oh ) ,
128	    .bin   (pri_complete_bin) 
129	  );
130	  
131	  fixed_pri_arb #(
132	    .ARB_WIDTH  (`LSU_NMSHRENTRY) 
133	  )
134	  nused_oh(
135	    .req    (~used          ) ,
136	    .grant  (pri_nused_oh   )   
137	  );
138	
139	  one2bin #(
140	    .ONE_WIDTH  (`LSU_NMSHRENTRY        ) ,
141	    .BIN_WIDTH  ($clog2(`LSU_NMSHRENTRY)) 
142	  )
143	  nused_bin(
144	    .oh    (pri_nused_oh    ) ,
145	    .bin   (pri_nused_bin   ) 
146	  );
147	
148	  //output entry and valid entry
149	  wire [$clog2(`LSU_NMSHRENTRY)-1:0] output_entry       ;
150	  wire [$clog2(`LSU_NMSHRENTRY)-1:0] valid_entry        ;
151	  assign output_entry = (|complete) ? pri_complete_bin : 'd0           ;
152	  assign valid_entry  = (&used)     ? 'd0              : pri_nused_bin ;
153	
154	  //fsm defines
155	  localparam S_IDLE  = 2'b00,
156	             S_ADD   = 2'b01,
157	             S_OUT_1 = 2'b10,
158	             S_OUT_2 = 2'b11;
159	
160	  reg [1:0] c_state ;
161	  reg [1:0] n_state ;
162	
163	  //output ready signals and idx_entry
164	  assign from_dcache_ready_o = c_state == S_IDLE             ;
165	  assign from_addr_ready_o   = (c_state==S_IDLE) && !(&used) ;
166	  assign idx_entry_o         = (from_addr_valid_i&&from_addr_ready_o) ? valid_entry : 'd0 ;
167	
168	  //bitset: for used and complete
169	  wire [`LSU_NMSHRENTRY-1:0] valid_entry_true   ;
170	  wire [`LSU_NMSHRENTRY-1:0] valid_entry_false  ;
171	  wire [`LSU_NMSHRENTRY-1:0] output_entry_true  ;
172	  wire [`LSU_NMSHRENTRY-1:0] output_entry_false ;
173	
174	  bin2one #(
175	    .ONE_WIDTH  (`LSU_NMSHRENTRY        ) ,
176	    .BIN_WIDTH  ($clog2(`LSU_NMSHRENTRY))
177	  )
178	  valid_entry_oh(
179	    .bin    (valid_entry      ) ,
180	    .oh     (valid_entry_true )   
181	  );
182	
183	  bin2one #(
184	    .ONE_WIDTH  (`LSU_NMSHRENTRY        ) ,
185	    .BIN_WIDTH  ($clog2(`LSU_NMSHRENTRY))
186	  )
187	  output_entry_oh(
188	    .bin    (output_entry     ) ,
189	    .oh     (output_entry_true)   
190	  );
191	
192	  assign valid_entry_false  = ~valid_entry_true  ;
193	  assign output_entry_false = ~output_entry_true ;
194	
195	  //fsm state transfer
196	  always@(posedge clk or negedge rst_n) begin
197	    if(!rst_n) begin
198	      c_state <= 2'b00;
199	    end
200	    else begin
201	      c_state <= n_state;
202	    end
203	  end
204	
205	  always@(*) begin
206	    case(c_state)
207	      S_IDLE  :begin
208	        if(from_dcache_ready_o && from_dcache_valid_i) begin
209	          if(from_addr_ready_o && from_addr_valid_i) begin
210	            n_state = S_ADD;
211	          end
212	          else if(current_mask[`NUM_THREAD*(from_dcache_instrid_i+1)-1 -:`NUM_THREAD]==from_dcache_activemask_i) begin
213	            n_state = S_OUT_1;
214	          end
215	          else begin
216	            n_state = S_IDLE;
217	          end
218	        end
219	        else if(|complete) begin
220	          n_state = S_OUT_1;
221	        end
222	        else begin
223	          n_state = S_IDLE;
224	        end
225	      end
226	      S_ADD   :begin
227	        if(|complete) begin
228	          n_state = S_OUT_1;
229	        end
230	        else begin
231	          n_state = S_IDLE;
232	        end
233	      end
234	      S_OUT_1 :begin
235	        if(to_pipe_ready_i) begin
236	          n_state = S_OUT_2;
237	        end
238	        else begin
239	          n_state = S_OUT_1;
240	        end
241	      end
242	      S_OUT_2 :begin
243	        if(to_pipe_ready_i) begin
244	          if(|(complete&output_entry_false)) begin
245	            n_state = S_OUT_1;
246	          end
247	          else begin
248	            n_state = S_IDLE;
249	          end
250	        end
251	        else begin
252	          n_state = S_OUT_2;
253	        end
254	      end
255	      default :begin
256	        n_state = S_IDLE;
257	      end
258	    endcase
259	  end 
260	
261	  always@(posedge clk or negedge rst_n) begin
262	    if(!rst_n) begin
263	      used         <= 'd0;
264	      current_mask <= 'd0;
265	      reg_req_mask <= 'd0;
266	    end
267	    else begin
268	      case(c_state)
269	        S_IDLE  : begin
270	          if(from_dcache_valid_i && from_dcache_ready_o) begin
271	            used <= used;
272	            current_mask[`NUM_THREAD*(from_dcache_instrid_i+1)-1 -:`NUM_THREAD] <= current_mask[`NUM_THREAD*(from_dcache_instrid_i+1)-1 -:`NUM_THREAD] & inv_activemask;
273	            if(from_addr_valid_i && from_addr_ready_o) begin
274	              reg_req_mask <= from_addr_mask_i;
275	            end
276	            else begin
277	              reg_req_mask <= reg_req_mask;
278	            end
279	          end
280	          else if(from_addr_valid_i && from_addr_ready_o) begin
281	            used <= used | valid_entry_true;
282	            reg_req_mask <= reg_req_mask;
283	            current_mask[`NUM_THREAD*(valid_entry+1)-1 -:`NUM_THREAD] <= from_addr_mask_i;
284	          end
285	          else begin
286	            used         <= used        ;
287	            reg_req_mask <= reg_req_mask;
288	            current_mask <= current_mask;
289	          end
290	        end
291	        S_ADD   : begin
292	          used         <= used | valid_entry_true;
293	          reg_req_mask <= reg_req_mask           ;
294	          current_mask[`NUM_THREAD*(valid_entry+1)-1 -:`NUM_THREAD] <= reg_req_mask;
295	        end
296	        S_OUT_2 : begin
297	          reg_req_mask <= reg_req_mask;
298	          current_mask <= current_mask;
299	          if(to_pipe_valid_o && to_pipe_ready_i) begin
300	            used <= used & output_entry_false;
301	          end
302	          else begin
303	            used <= used;
304	          end
305	        end
306	        default : begin
307	          used         <= used        ;
308	          reg_req_mask <= reg_req_mask;
309	          current_mask <= current_mask;
310	        end
311	      endcase
312	    end
313	  end
314	
315	  assign sram_in_tag_warp_id      = from_addr_warp_id_i     ;
316	  assign sram_in_tag_wfd          = from_addr_wfd_i         ;
317	  assign sram_in_tag_wxd          = from_addr_wxd_i         ;
318	  assign sram_in_tag_reg_idxw     = from_addr_reg_idxw_i    ;
319	  assign sram_in_tag_mask         = from_addr_mask_i        ;
320	  assign sram_in_tag_unsigned     = from_addr_unsigned_i    ;
321	  assign sram_in_tag_wordoffset1h = from_addr_wordoffset1h_i;
322	  assign sram_in_tag_iswrite      = from_addr_iswrite_i     ;
323	
324	  assign sram_in_tag_bits = {sram_in_tag_warp_id     ,  
325	                             sram_in_tag_wfd         ,
326	                             sram_in_tag_wxd         ,
327	                             sram_in_tag_reg_idxw    ,
328	                             sram_in_tag_mask        ,
329	                             sram_in_tag_unsigned    ,
330	                             sram_in_tag_wordoffset1h,
331	                             sram_in_tag_iswrite     };  
332	
333	  assign sram_in_data_raddr = output_entry;
334	  
335	  assign sram_in_tag_raddr = output_entry;
336	  assign sram_in_tag_waddr = valid_entry ;
337	  assign sram_in_tag_wmask = {(4+`NUM_THREAD*5+`REGIDX_WIDTH+`REGEXT_WIDTH+`DEPTH_WARP){1'b1}};
338	
339	  //when state is S_OUT_1, read SRAM;
340	  //when state is S_OUT_2, output SRAM results;
341	  assign sram_in_tag_ren   = c_state == S_OUT_1;
342	  assign sram_in_data_ren  = c_state == S_OUT_1;
343	
344	  wire [`XLEN*`NUM_THREAD-1:0] from_dcache_mask_to_sram;
345	
346	  always@(*) begin
347	    case(c_state)
348	      S_IDLE  :begin
349	        if(from_dcache_ready_o && from_dcache_valid_i) begin //write data
350	          sram_in_data_wen   = 1'b1                       ;
351	          sram_in_data_wmask = from_dcache_mask_to_sram   ;
352	          sram_in_data_waddr = from_dcache_instrid_i      ;
353	          sram_in_data_bits  = from_dcache_data_i         ;
354	          sram_in_tag_wen    = 1'b0                       ;
355	        end
356	        else if(from_addr_ready_o && from_addr_valid_i) begin //accept tag, empty data
357	          sram_in_data_wen   = 1'b1                       ;
358	          sram_in_data_wmask = {(`NUM_THREAD*`XLEN){1'b1}};
359	          sram_in_data_waddr = valid_entry                ;
360	          sram_in_data_bits  = 'd0                        ;
361	          sram_in_tag_wen    = 1'b1                       ;
362	        end
363	        else begin //no operation
364	          sram_in_data_wen   = 1'b0                       ;
365	          sram_in_data_wmask = {(`NUM_THREAD*`XLEN){1'b1}};
366	          sram_in_data_waddr = valid_entry                ;
367	          sram_in_data_bits  = 'd0                        ;
368	          sram_in_tag_wen    = 1'b0                       ;
369	        end
370	      end
371	      S_ADD:   begin //update tag information
372	        sram_in_data_wen   = 1'b1                       ;
373	        sram_in_data_wmask = {(`NUM_THREAD*`XLEN){1'b1}};
374	        sram_in_data_waddr = valid_entry                ;
375	        sram_in_data_bits  = 'd0                        ;
376	        sram_in_tag_wen    = 1'b1                       ;
377	      end
378	      default: begin //no operation
379	        sram_in_data_wen   = 1'b0                       ;
380	        sram_in_data_wmask = {(`NUM_THREAD*`XLEN){1'b0}};
381	        sram_in_data_waddr = valid_entry                ;
382	        sram_in_data_bits  = 'd0                        ;
383	        sram_in_tag_wen    = 1'b0                       ;
384	      end
385	    endcase
386	  end
387	
388	  //output to pipe: tag
389	  wire [`XLEN*`NUM_THREAD-1:0]           raw_data            ;
390	  wire [`XLEN*`NUM_THREAD-1:0]           extract_data        ;
391	  wire [`XLEN*`NUM_THREAD-1:0]           output_data         ;
392	
393	  assign raw_data = sram_out_data_bits;
394	
395	  genvar j;
396	  generate for(j=0;j<`NUM_THREAD;j=j+1) begin: OUTPUT_DATA
397	    assign from_dcache_mask_to_sram[`XLEN*(j+1)-1-:`XLEN] = from_dcache_activemask_i[j] ? {`XLEN{1'b1}} : {`XLEN{1'b0}}; 
398	
399	    byte_extract raw(
400	      .is_uint    (to_pipe_unsigned                                         ),
401	      .sel        (to_pipe_wordoffset1h[`BYTESOFWORD*(j+1)-1:`BYTESOFWORD*j]),
402	      .in         (raw_data[`XLEN*(j+1)-1:`XLEN*j]                          ),
403	      .result     (extract_data[`XLEN*(j+1)-1:`XLEN*j]                      )
404	    );
405	
406	    assign output_data[`XLEN*(j+1)-1:`XLEN*j] = extract_data[`XLEN*(j+1)-1:`XLEN*j] ;
407	  end
408	  endgenerate
409	
410	  assign to_pipe_valid_o      = c_state==S_OUT_2 && (|complete)                                                            ;
411	  assign to_pipe_warp_id_o    = sram_out_tag_bits[3+`NUM_THREAD*5+`REGIDX_WIDTH+`REGEXT_WIDTH+`DEPTH_WARP-:`DEPTH_WARP]    ;
412	  assign to_pipe_wfd_o        = sram_out_tag_bits[3+`NUM_THREAD*5+`REGIDX_WIDTH+`REGEXT_WIDTH]                             ;
413	  assign to_pipe_wxd_o        = sram_out_tag_bits[2+`NUM_THREAD*5+`REGIDX_WIDTH+`REGEXT_WIDTH]                             ;
414	  assign to_pipe_reg_idxw_o   = sram_out_tag_bits[1+`NUM_THREAD*5+`REGIDX_WIDTH+`REGEXT_WIDTH-:`REGIDX_WIDTH+`REGEXT_WIDTH];
415	  assign to_pipe_mask_o       = sram_out_tag_bits[1+`NUM_THREAD*5-:`NUM_THREAD]                                            ;
416	  assign to_pipe_unsigned     = sram_out_tag_bits[`NUM_THREAD*4]                                                           ;
417	  assign to_pipe_wordoffset1h = sram_out_tag_bits[`NUM_THREAD*4-:`NUM_THREAD*4]                                            ;
418	  assign to_pipe_iswrite_o    = sram_out_tag_bits[0]                                                                       ;
419	  assign to_pipe_data_o       = output_data;
420	
421	  dualportSRAM #(
422	    .BITWIDTH   (`XLEN*`NUM_THREAD      ),
423	    .DEPTH      ($clog2(`LSU_NMSHRENTRY))
424	  )
425	  mshr_data (
426	    .CLK  (clk               ),
427	    .RSTN (rst_n             ),
428	    .D    (sram_in_data_bits ),
429	    .Q    (sram_out_data_bits),
430	    .REB  (sram_in_data_ren  ),
431	    .WEB  (sram_in_data_wen  ), 
432	    .BWEB (sram_in_data_wmask), 
433	    .AA   (sram_in_data_waddr), 
434	    .AB   (sram_in_data_raddr) 
435	  );
436	
437	  dualportSRAM #(
438	    .BITWIDTH   (4+`NUM_THREAD*5+`REGIDX_WIDTH+`REGEXT_WIDTH+`DEPTH_WARP),
439	    .DEPTH      ($clog2(`LSU_NMSHRENTRY)                                )
440	  )
441	  mshr_tag (
442	    .CLK  (clk              ),
443	    .RSTN (rst_n            ),
444	    .D    (sram_in_tag_bits ),
445	    .Q    (sram_out_tag_bits),
446	    .REB  (sram_in_tag_ren  ),
447	    .WEB  (sram_in_tag_wen  ), 
448	    .BWEB (sram_in_tag_wmask), 
449	    .AA   (sram_in_tag_waddr), 
450	    .AB   (sram_in_tag_raddr) 
451	  );
452	    
453	
454	endmodule
455

