11	// Author: Tan, Zhiyuan
12	// Description: Compute the addr of requests, and send them.
13	
14	`timescale 1ns/1ns
15	
16	`include "define.v"
17	//`include "IDecode_define.v"
18	
19	module addrcalculate #(parameter SHARED_ADDR_MAX = 32'd4096)(
20	  input                                             clk                       ,
21	  input                                             rst_n                     ,
22	
23	  //from fifo(vExeData)
24	  input                                             from_fifo_valid_i         ,
25	  output                                            from_fifo_ready_o         ,
26	  input   [`XLEN*`NUM_THREAD-1:0]                   from_fifo_in1_i           ,
27	  input   [`XLEN*`NUM_THREAD-1:0]                   from_fifo_in2_i           ,
28	  input   [`XLEN*`NUM_THREAD-1:0]                   from_fifo_in3_i           ,
29	  input   [`NUM_THREAD-1:0]                         from_fifo_mask_i          ,
30	  //from fifo: control signals
31	  input   [`DEPTH_WARP-1:0]                         from_fifo_wid_i           ,
32	  input                                             from_fifo_isvec_i         ,
33	  input   [1:0]                                     from_fifo_mem_whb_i       ,
34	  input                                             from_fifo_mem_unsigned_i  ,
35	  input   [5:0]                                     from_fifo_alu_fn_i        ,
36	  input                                             from_fifo_is_vls12_i      ,
37	  input                                             from_fifo_disable_mask_i  ,
38	  input   [1:0]                                     from_fifo_mem_cmd_i       ,
39	  input   [1:0]                                     from_fifo_mop_i           ,
40	  input   [`REGIDX_WIDTH+`REGEXT_WIDTH-1:0]         from_fifo_reg_idxw_i      ,
41	  input                                             from_fifo_wvd_i           ,
42	  input                                             from_fifo_fence_i         ,
43	  input                                             from_fifo_wxd_i           ,
44	  input                                             from_fifo_atomic_i        ,
45	  input                                             from_fifo_aq_i            ,
46	  input                                             from_fifo_rl_i            ,
47	
48	  //connect csr
49	  input   [`XLEN-1:0]                               csr_pds_i                 ,
50	  input   [`XLEN-1:0]                               csr_numw_i                ,
51	  input   [`XLEN-1:0]                               csr_tid_i                 ,
52	  output  [`DEPTH_WARP-1:0]                         csr_wid_o                 ,
53	
54	  //idx entry
55	  input   [$clog2(`LSU_NMSHRENTRY)-1:0]             idx_entry_i               ,
56	  
57	  //to mshr
58	  output                                            to_mshr_valid_o           ,
59	  input                                             to_mshr_ready_i           ,
60	  output  [`DEPTH_WARP-1:0]                         to_mshr_warp_id_o         ,
61	  output                                            to_mshr_wfd_o             ,
62	  output                                            to_mshr_wxd_o             ,
63	  //output                                            to_mshr_isvec_o           ,
64	  output  [`REGIDX_WIDTH+`REGEXT_WIDTH-1:0]         to_mshr_reg_idxw_o        ,
65	  output  [`NUM_THREAD-1:0]                         to_mshr_mask_o            ,
66	  output                                            to_mshr_unsigned_o        ,
67	  output  [`BYTESOFWORD*`NUM_THREAD-1:0]            to_mshr_wordoffset1h_o    ,
68	  output                                            to_mshr_iswrite_o         ,
69	
70	  //to shared
71	  output                                            to_shared_valid_o         ,
72	  input                                             to_shared_ready_i         ,
73	  output  [$clog2(`LSU_NMSHRENTRY)-1:0]             to_shared_instrid_o       ,
74	  output                                            to_shared_iswrite_o       ,
75	  output  [`DCACHE_TAGBITS-1:0]                     to_shared_tag_o           ,
76	  output  [`DCACHE_SETIDXBITS-1:0]                  to_shared_setidx_o        ,
77	  output  [`NUM_THREAD-1:0]                         to_shared_activemask_o    ,
78	  output  [`NUM_THREAD*`DCACHE_BLOCKOFFSETBITS-1:0] to_shared_blockoffset_o   ,
79	  output  [`NUM_THREAD*`BYTESOFWORD-1:0]            to_shared_wordoffset1h_o  ,
80	  output  [`NUM_THREAD*`XLEN-1:0]                   to_shared_data_o          ,
81	
82	  //to dcache
83	  output                                            to_dcache_valid_o         ,
84	  input                                             to_dcache_ready_i         ,
85	  output  [$clog2(`LSU_NMSHRENTRY)-1:0]             to_dcache_instrid_o       ,
86	  output  [`DCACHE_SETIDXBITS-1:0]                  to_dcache_setidx_o        ,
87	  output  [`DCACHE_TAGBITS-1:0]                     to_dcache_tag_o           ,
88	  output  [`NUM_THREAD-1:0]                         to_dcache_activemask_o    ,
89	  output  [`NUM_THREAD*`DCACHE_BLOCKOFFSETBITS-1:0] to_dcache_blockoffset_o   ,
90	  output  [`NUM_THREAD*`BYTESOFWORD-1:0]            to_dcache_wordoffset1h_o  ,
91	  output  [`NUM_THREAD*`XLEN-1:0]                   to_dcache_data_o          ,
92	  output  [2:0]                                     to_dcache_opcode_o        ,
93	  output  [3:0]                                     to_dcache_param_o         
94	  );
95	
96	  //fsm and counter defines
97	  localparam S_IDLE     = 3'b000,
98	             S_SAVE     = 3'b001,
99	             S_SHARED   = 3'b010,
100	             S_DCACHE   = 3'b011,
101	             S_DCACHE_1 = 3'b100,
102	             S_DCACHE_2 = 3'b101;
103	
104	  parameter DCACHE_TAGBITS = `DCACHE_TAGBITS ;
105	
106	  reg  [2:0]                            c_state              ;
107	  reg  [2:0]                            n_state              ;
108	  reg  [`DEPTH_THREAD-1:0]              cnt                  ;
109	  //reg_save
110	  //reg  [`XLEN*`NUM_THREAD-1:0]          reg_save_in1         ;
111	  //reg  [`XLEN*`NUM_THREAD-1:0]          reg_save_in2         ;
112	  reg  [`XLEN*`NUM_THREAD-1:0]          reg_save_in3         ;
113	  reg  [`NUM_THREAD-1:0]                reg_save_mask        ;
114	  reg  [`DEPTH_WARP-1:0]                reg_save_wid         ;
115	  reg                                   reg_save_isvec       ;
116	  reg  [1:0]                            reg_save_mem_whb     ;
117	  reg                                   reg_save_mem_unsigned;
118	  reg  [5:0]                            reg_save_alu_fn      ;
119	  //reg                                   reg_save_is_vls12    ;
120	  //reg                                   reg_save_disable_mask;
121	  reg  [1:0]                            reg_save_mem_cmd     ;
122	  //reg  [1:0]                            reg_save_mop         ;
123	  reg  [`REGIDX_WIDTH+`REGEXT_WIDTH-1:0]reg_save_reg_idxw    ;
124	  reg                                   reg_save_wvd         ;
125	  reg                                   reg_save_fence       ;
126	  reg                                   reg_save_wxd         ;
127	  reg                                   reg_save_atomic      ;
128	  reg                                   reg_save_aq          ;
129	  reg                                   reg_save_rl          ;
130	  //entry id
131	  reg [$clog2(`LSU_NMSHRENTRY)-1:0]     reg_entryid          ;
132	
133	  //input ready and output csr wid
134	  assign from_fifo_ready_o = c_state==S_IDLE;
135	  assign csr_wid_o = reg_save_wid;
136	
137	  //Addr caculate and analyze(comb)
