660	    end
661	    else begin
662	      case(c_state)
663	        S_IDLE    : begin
664	          if(from_fifo_valid_i && from_fifo_ready_o) begin
665	            //reg_save_in1          <= from_fifo_in1_i          ;
666	            //reg_save_in2          <= from_fifo_in2_i          ;
667	            reg_save_in3          <= from_fifo_in3_i          ;
668	            reg_save_mask         <= from_fifo_mask_i         ;
669	            reg_save_wid          <= from_fifo_wid_i          ;
670	            reg_save_isvec        <= from_fifo_isvec_i        ;
671	            reg_save_mem_whb      <= from_fifo_mem_whb_i      ;
672	            reg_save_mem_unsigned <= from_fifo_mem_unsigned_i ;
673	            reg_save_alu_fn       <= from_fifo_alu_fn_i       ;
674	            //reg_save_is_vls12     <= from_fifo_is_vls12_i     ;
675	            //reg_save_disable_mask <= from_fifo_disable_mask_i ;
676	            reg_save_mem_cmd      <= from_fifo_mem_cmd_i      ;
677	            //reg_save_mop          <= from_fifo_mop_i          ;
678	            reg_save_reg_idxw     <= from_fifo_reg_idxw_i     ;
679	            reg_save_wvd          <= from_fifo_wvd_i          ;
680	            reg_save_fence        <= from_fifo_fence_i        ;
681	            reg_save_wxd          <= from_fifo_wxd_i          ;
682	            reg_save_atomic       <= from_fifo_atomic_i       ;
683	            reg_save_aq           <= from_fifo_aq_i           ;
684	            reg_save_rl           <= from_fifo_rl_i           ;
685	          end
686	          else begin
687	            //reg_save_in1          <= 'd0 ;
688	            //reg_save_in2          <= 'd0 ;
689	            reg_save_in3          <= 'd0 ;
690	            reg_save_mask         <= 'd0 ;
691	            reg_save_wid          <= 'd0 ;
692	            reg_save_isvec        <= 'd0 ;
693	            reg_save_mem_whb      <= 'd0 ;
694	            reg_save_mem_unsigned <= 'd0 ;
695	            reg_save_alu_fn       <= 'd0 ;
696	            //reg_save_is_vls12     <= 'd0 ;
697	            //reg_save_disable_mask <= 'd0 ;
698	            reg_save_mem_cmd      <= 'd0 ;
699	            //reg_save_mop          <= 'd0 ;
700	            reg_save_reg_idxw     <= 'd0 ;
701	            reg_save_wvd          <= 'd0 ;
702	            reg_save_fence        <= 'd0 ;
703	            reg_save_wxd          <= 'd0 ;
704	            reg_save_atomic       <= 'd0 ;
705	            reg_save_aq           <= 'd0 ;
706	            reg_save_rl           <= 'd0 ;
707	          end
708	        end
709	        S_SHARED  : begin
710	          if(to_shared_ready_i && to_shared_valid_o) begin
711	            reg_save_mask <= mask_next;
712	          end
713	          else begin
714	            reg_save_mask <= reg_save_mask;
715	          end
716	        end
717	        S_DCACHE  : begin
718	          if(to_dcache_ready_i && to_dcache_valid_o) begin
719	            reg_save_mask <= mask_next;
720	          end
721	          else begin
722	            reg_save_mask <= reg_save_mask;
723	          end
724	        end
725	        default   : begin
726	          //reg_save_in1          <= reg_save_in1          ;
727	          //reg_save_in2          <= reg_save_in2          ;
728	          reg_save_in3          <= reg_save_in3          ;
729	          reg_save_mask         <= reg_save_mask         ;
730	          reg_save_wid          <= reg_save_wid          ;
731	          reg_save_isvec        <= reg_save_isvec        ;
732	          reg_save_mem_whb      <= reg_save_mem_whb      ;
733	          reg_save_mem_unsigned <= reg_save_mem_unsigned ;
734	          reg_save_alu_fn       <= reg_save_alu_fn       ;
735	          //reg_save_is_vls12     <= reg_save_is_vls12     ;
736	          //reg_save_disable_mask <= reg_save_disable_mask ;
737	          reg_save_mem_cmd      <= reg_save_mem_cmd      ;
738	          //reg_save_mop          <= reg_save_mop          ;
739	          reg_save_reg_idxw     <= reg_save_reg_idxw     ;
740	          reg_save_wvd          <= reg_save_wvd          ;
741	          reg_save_fence        <= reg_save_fence        ;
742	          reg_save_wxd          <= reg_save_wxd          ;
743	          reg_save_atomic       <= reg_save_atomic       ;
744	          reg_save_aq           <= reg_save_aq           ;
745	          reg_save_rl           <= reg_save_rl           ;
746	        end
747	      endcase
748	    end
749	  end
750	
751	endmodule
752

